begin;
with j as (select * from jsonb_to_recordset($law7d0036$[{"code_id":"BK_RF","article_number":"69.2","version_date":"1998-07-31","article_text":"1. Государственное (муниципальное)  задание должно содержать:\n\nабзац; (Утратил силу - Федеральный закон от 08.05.2010 № 83-ФЗ)\n\nпоказатели,  характеризующие качество и (или)  объем (содержание)  оказываемых государственных (муниципальных)  услуг (выполняемых работ) ; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nпорядок контроля за исполнением государственного (муниципального)  задания,  в том числе условия и порядок его досрочного прекращения;\n\nтребования к отчетности об исполнении государственного (муниципального)  задания.\n\nГосударственное (муниципальное)  задание на оказание государственных (муниципальных)  услуг физическим и юридическим лицам также должно содержать:\n\nопределение категорий физических и (или)  юридических лиц,  являющихся потребителями соответствующих услуг;\n\nпорядок оказания соответствующих услуг;\n\nпредельные цены (тарифы)  на оплату соответствующих услуг физическими или юридическими лицами в случаях,  если законодательством Российской Федерации предусмотрено их оказание на платной основе,  либо порядок установления указанных цен (тарифов)  в случаях,  установленных законодательством Российской Федерации. (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\n(Пункт в редакции Федерального закона от 30.12.2008 № 310-ФЗ)\n\n2. Показатели государственного (муниципального)  задания используются при составлении проектов бюджетов для планирования бюджетных ассигнований на оказание государственных (муниципальных)  услуг (выполнение работ) ,  составлении бюджетной сметы казенного учреждения,  а также для определения объема субсидий на выполнение государственного (муниципального)  задания бюджетным или автономным учреждением. (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\n3. Государственное (муниципальное)  задание на оказание государственных (муниципальных)  услуг (выполнение работ)  федеральными учреждениями,  учреждениями субъекта Российской Федерации,  муниципальными учреждениями формируется в порядке,  установленном соответственно Правительством Российской Федерации,  высшим исполнительным органом субъекта Российской Федерации,  местной администрацией муниципального образования,  на срок до одного года в случае утверждения бюджета на очередной финансовый год и на срок до трех лет в случае утверждения бюджета на очередной финансовый год и плановый период (с возможным уточнением при составлении проекта бюджета) . (В редакции  федеральных законов от 08.05.2010 № 83-ФЗ,  от 23.07.2013 № 252-ФЗ,  от 18.07.2017 № 178-ФЗ,  от 14.04.2023 № 128-ФЗ)\n\nГосударственное (муниципальное)  задание в части государственных (муниципальных)  услуг,  оказываемых федеральными учреждениями,  учреждениями субъекта Российской Федерации,  муниципальными учреждениями физическим лицам,  формируется в соответствии с общероссийскими базовыми (отраслевыми)  перечнями (классификаторами)  государственных и муниципальных услуг,  оказываемых физическим лицам,  формирование,  ведение и утверждение которых осуществляется в порядке,  установленном Правительством Российской Федерации. Включение в указанные перечни (классификаторы)  положений,  приводящих к возникновению расходных обязательств субъектов Российской Федерации (муниципальных образований) ,  не допускается. (Дополнение абзацем - Федеральный закон от 18.07.2017 № 178-ФЗ)\n\nФедеральные органы государственной власти вправе формировать государственное задание на оказание государственных услуг (выполнение работ)  федеральными учреждениями также в соответствии с федеральными перечнями (классификаторами)  государственных услуг,  не включенных в общероссийские базовые (отраслевые)  перечни (классификаторы)  государственных и муниципальных услуг,  и работ,  оказание и выполнение которых предусмотрено нормативными правовыми актами Российской Федерации. Формирование,  ведение и утверждение федеральных перечней (классификаторов)  государственных услуг и работ осуществляется в порядке,  установленном Правительством Российской Федерации. (Дополнение абзацем - Федеральный закон от 18.07.2017 № 178-ФЗ)\n\nОрганы государственной власти субъектов Российской Федерации (органы местного самоуправления)  вправе формировать государственное (муниципальное)  задание на оказание государственных (муниципальных)  услуг и выполнение работ учреждениями субъекта Российской Федерации (муниципальными учреждениями муниципальных образований,  находящихся на территории данного субъекта Российской Федерации)  также в соответствии с региональным перечнем (классификатором)  государственных (муниципальных)  услуг,  не включенных в общероссийские базовые (отраслевые)  перечни (классификаторы)  государственных и муниципальных услуг,  и работ,  оказание и выполнение которых предусмотрено нормативными правовыми актами субъекта Российской Федерации (муниципальными правовыми актами) ,  в том числе при осуществлении переданных им полномочий Российской Федерации и полномочий по предметам совместного ведения Российской Федерации и субъектов Российской Федерации. Формирование,  ведение и утверждение регионального перечня (классификатора)  государственных (муниципальных)  услуг и работ осуществляется в порядке,  установленном высшим исполнительным органом субъекта Российской Федерации. Включение в указанный перечень (классификатор)  положений,  приводящих к возникновению расходных обязательств муниципальных образований,  не допускается. (Дополнение абзацем - Федеральный закон от 18.07.2017 № 178-ФЗ)  (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nРегиональные перечни (классификаторы)  государственных (муниципальных)  услуг и работ размещаются на официальном сайте для размещения информации о государственных и муниципальных учреждениях и на едином портале бюджетной системы Российской Федерации в информационно-телекоммуникационной сети \"Интернет\" в порядке,  установленном Министерством финансов Российской Федерации. (Дополнение абзацем - Федеральный закон от 18.07.2017 № 178-ФЗ)\n\nГосударственное (муниципальное)  задание формируется для бюджетных и автономных учреждений,  а также казенных учреждений,  определенных в соответствии с решением органа государственной власти (государственн\n\nановлено иное; (Дополнение абзацем - Федеральный закон от 26.12.2014 № 450-ФЗ)\n\nплата по соглашениям об установлении сервитута,  заключенным исполнительными органами субъектов Российской Федерации,  государственными или муниципальными предприятиями либо государственными или муниципальными учреждениями в отношении земельных участков,  которые расположены в границах городских,  сельских поселений,  находятся в федеральной собственности и осуществление полномочий Российской Федерации по управлению и распоряжению которыми передано органам государственной власти субъектов Российской Федерации,  - по нормативу не менее 50 процентов,  если законодательством соответствующего субъекта Российской Федерации не установлено иное; (Дополнение абзацем - Федеральный закон от 26.12.2014 № 450-ФЗ)  (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nплата за публичный сервитут,  предусмотренная решением уполномоченного органа об установлении публичного сервитута в отношении земельных участков,  которые расположены в границах городских,  сельских поселений и находятся в федеральной собственности,  осуществление полномочий Российской Федерации по управлению и распоряжению которыми передано органам государственной власти субъектов Российской Федерации и которые не предоставлены гражданам или юридическим лицам (за исключением органов государственной власти (государственных органов) ,  органов местного самоуправления (муниципальных органов) ,  органов управления государственными внебюджетными фондами и казенных учреждений) ,  - по нормативу не менее 50 процентов,  если законодательством соответствующего субъекта Российской Федерации не установлено иное. (Дополнение абзацем - Федеральный закон от 01.07.2021 № 251-ФЗ)\n\n(Дополнение частью - Федеральный закон от 24.07.2008 № 161-ФЗ)\n\nВ бюджеты соответствующих видов муниципальных образований подлежат зачислению неналоговые доходы по нормативам отчислений,  установленным органами государственной власти субъектов Российской Федерации в соответствии со статьей 58 настоящего Кодекса. (Дополнение частью - Федеральный закон от 02.08.2019 № 307-ФЗ)\n\nВ бюджеты городских,  сельских поселений (внутригородских районов)  подлежат зачислению неналоговые доходы по нормативам отчислений,  установленным представительным органом муниципального района (городского округа с внутригородским делением)  в соответствии со статьями 63 и 631 настоящего Кодекса. (Дополнение частью - Федеральный закон от 02.08.2019 № 307-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 69.2. Государственное (муниципальное)  задание","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9f8b4888b69df3141f51094704adb29f3bccec6f411a90dcebab1dbf083e9017"},{"code_id":"BK_RF","article_number":"7","version_date":"1998-07-31","article_text":"К бюджетным полномочиям Российской Федерации относятся:\n\nустановление общих принципов организации и функционирования бюджетной системы Российской Федерации,  основ бюджетного процесса и межбюджетных отношений;\n\nопределение основ составления и рассмотрения проектов бюджетов бюджетной системы Российской Федерации,  утверждения и исполнения бюджетов бюджетной системы Российской Федерации,  составления,  внешней проверки,  рассмотрения и утверждения отчетов об их исполнении и осуществления контроля за их исполнением;\n\nустановление порядка составления и рассмотрения проектов федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации,  утверждения и исполнения федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации,  осуществления контроля за их исполнением,  составление,  внешняя проверка,  рассмотрения и утверждения отчетов об исполнении федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации,  составления отчета об исполнении консолидированного бюджета Российской Федерации;\n\nсоставление и рассмотрение проектов федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации,  утверждение и исполнение федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации,  осуществление контроля за их исполнением,  составления,  внешняя проверка,  рассмотрение и утверждение отчетов об исполнении федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации,  составление отчета об исполнении консолидированного бюджета Российской Федерации;\n\nустановление порядка составления и представления в федеральные органы исполнительной власти сводов утвержденных бюджетов субъектов Российской Федерации и местных бюджетов,  отчетов об исполнении консолидированных бюджетов субъектов Российской Федерации и иной бюджетной отчетности;\n\nопределение порядка установления расходных обязательств публично-правовых образований;\n\nопределение порядка установления и исполнения расходных обязательств Российской Федерации,  установление и исполнение расходных обязательств Российской Федерации;\n\nопределение порядка установления и исполнения расходных обязательств субъектов Российской Федерации и муниципальных образований,  подлежащих исполнению за счет субвенций из федерального бюджета;\n\nопределение основ формирования доходов и осуществления расходов бюджетов бюджетной системы Российской Федерации;\n\nопределение порядка установления нормативов отчислений доходов от федеральных налогов и сборов,  в том числе от налогов,  предусмотренных специальными налоговыми режимами,  региональных налогов,  местных налогов и сбор\n\nнизации и осуществления бюджетного процесса;\n\nмежбюджетные трансферты - средства,  предоставляемые одним бюджетом бюджетной системы Российской Федерации другому бюджету бюджетной системы Российской Федерации;\n\nдотации - межбюджетные трансферты,  предоставляемые на безвозмездной и безвозвратной основе без установления направлений их использования; (В редакции Федерального закона от 18.07.2017 № 172-ФЗ)\n\nбюджетные полномочия - установленные настоящим Кодексом и принятыми в соответствии с ним правовыми актами,  регулирующими бюджетные правоотношения,  права и обязанности органов государственной власти (органов местного самоуправления)  и иных участников бюджетного процесса по регулированию бюджетных правоотношений,  организации и осуществлению бюджетного процесса;\n\nсмета доходов и расходов населенного пункта,  другой территории,  не являющейся муниципальным образованием,  - утвержденный органом местного самоуправления городского,  сельского поселения,  внутригородского района,  муниципального района (в отношении населенного пункта,  другой территории,  расположенных на межселенной территории) ,  муниципального округа,  городского округа,  внутригородского муниципального образования города федерального значения Москвы,  Санкт-Петербурга или Севастополя план доходов и расходов распорядителя (главного распорядителя)  средств местного бюджета,  уполномоченного местной администрацией городского,  сельского поселения,  внутригородского района,  муниципального района (в отношении населенного пункта,  другой территории,  расположенных на межселенной территории) ,  муниципального округа,  городского округа,  внутригородского муниципального образования города федерального значения Москвы,  Санкт-Петербурга или Севастополя осуществлять в данном населенном пункте,  на другой территории,  входящих в состав территории городского,  сельского поселения,  внутригородского района,  муниципального района (в отношении населенного пункта,  другой территории,  расположенных на межселенной территории) ,  муниципального округа,  городского округа,  внутригородского муниципального образования города федерального значения Москвы,  Санкт-Петербурга или Севастополя,  отдельные функции местной администрации; (В редакции федеральных законов от 29.11.2014 № 383-ФЗ,  от 01.10.2020 № 311-ФЗ)\n\nабзац; (Утратил силу  - Федеральный закон от 27.12.2019 № 479-ФЗ)\n\nказначейский счет - счет,  открытый в Федеральном казначействе отдельному участнику системы казначейских платежей для осуществления и отражения в системе казначейских платежей операций участника системы казначейских платежей с денежными средствами; (Дополнение абзацем - Федеральный закон от 27.12.2019 № 479-ФЗ)\n\nединый казначейский счет - банковский счет (совокупность банковских счетов) ,  за исключением счета цифрового рубля Федерального казначейства,  открытый (открытых)  Федеральному казначейству в Центральном банке Российской Федерации в валюте Российской Федерации (в кредитных организациях - в иностранной валюте)  для совершения переводов денежных средств в целях обеспечения осуществления и отражения операций на казначейских счетах,  за исключением казначейских счетов для осуществления и отражения операций с денежными средствами Фонда национального благосостояния; (Дополнение абзацем - Федеральный закон от 27.12.2019 № 479-ФЗ)  (В редакции  Федерального закона от 31.07.2025 № 303-ФЗ)\n\nединый счет бюджета - казначейский счет (совокупность казначейских счетов для федерального бюджета,  бюджетов государственных внебюджетных фондов Российской Федерации) ,  открытый (открытых)  в Федеральном казначействе отдельно по каждому бюджету бюджетной системы Российской Федерации для осуществления и отражения операций с денежными средствами по поступлениям в бюджет и перечислениям из бюджета; (В редакции Федерального закона от 27.12.2019 № 479-ФЗ)\n\nсчет цифрового рубля Федерального казначейства - счет цифрового рубля,  открытый Федеральному казначейству оператором платформы цифрового рубля для совершения операций с цифровыми рублями; (Дополнение абзацем - Федеральный закон от 31.07.2025 № 303-ФЗ)\n\nказначейское обслуживание - проведение Федеральным казначейством в системе казначейских платежей операций участников системы казначейских платежей с денежными средствами с их отражением на соответствующих казначейских счетах; (Дополнение абзацем - Федеральный закон от 27.12.2019 № 479-ФЗ)\n\nказначейский мониторинг - деятельность Федерального казначейства по своевременному предупреждению и предотвращению финансовых нарушений участников системы казначейских платежей; (Дополнение абзацем - Федеральный закон от 01.07.2021 № 244-ФЗ)  (В редакции  Федерального закона от 21.04.2025 № 84-ФЗ)\n\nучастник казначейского сопровождения - юридическое лицо,  индивидуальный предприниматель,  физическое лицо - производитель товаров,  работ,  услуг,  получающие средства,  определенные в соответствии с главой 244 настоящего Кодекса,  использование которых осуществляется после подтверждения на соответствие условиям и (или)  целям,  установленным при предоставлении средств; (Дополнение абзацем - Федеральный закон от 01.07.2021 № 244-ФЗ)  (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\nказначейское сопровождение - проведение Федеральным казначейством (финансовыми органами субъектов Российской Федерации (муниципальных образований)  операций с денежными средствами участника казначейского сопровождения; (Дополнение абзацем - Федеральный закон от 01.07.2021 № 244-ФЗ)\n\nгосударственные (муниципальные)  услуги (работы)  - услуги (работы) ,  оказываемые (выполняемые)  органами государственной власти (органами местного самоуправления) ,  государственными (муниципальными)  учреждениями и в случаях,  установленных законодательством Российской Федерации,  иными юридическими лицами; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nгосударственное (муниципальное)  задание - документ,  устанавливающий требования к составу,  качеству и (или)  объему (содержанию) ,  условиям,  порядку и результатам оказания государственных (муниципальных)  услуг (выполнения работ) ; (В редакции Федерального закона от 30.12.2008 № 310-ФЗ)\n\nбюджетные инвестиции - бюджетные средства,  направляемые на создание или увеличение за счет средств бюджета стоимости государственного (муниципального)  имущества;\n\nналоговые расходы публично-правового образования - выпадающие доходы бюджетов бюджетной системы Российской Федерации,  обусловленные налоговыми льготами,  освобождениями и иными преференциями по налогам,  сборам,  таможенным платежам,  страховым взносам на обязательное социальное страхование,  предусмотренными в качестве мер государственной (муниципальной)  поддержки в соответствии с целями государственных (муниципальных)  программ и (или)  целями социально-экономической политики публично-правового образования,  не относящимися к государственным (муниципальным)  программам; (Дополнение абзацем - Федеральный закон от 25.12.2018 № 494-ФЗ)\n\nфинансовые органы - Министерство финансов Российской Федерации,  исполнительные органы субъектов Российской Федерации,  осуществляющие составление и организацию исполнения бюджетов субъектов Российской Федерации (финансовые органы субъектов Российской Федерации) ,  органы (должностные лица)  местных администраций муниципальных образований,  осуществляющие составление и организацию исполнения местных бюджетов (финансовые органы муниципальных образований) ; (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nглавный распорядитель бюджетных средств (главный распорядитель средств соответствующего бюджета)  - орган государственной власти (государственный орган) ,  орган управления государственным внебюджетным фондом,  орган местного самоуправления,  орган местной администрации,  а также наиболее значимое учреждение науки,  образования,  культуры и здравоохранения,  указанное в ведомственной структуре расходов бюджета,  имеющие право распределять бюджетные ассигнования и лимиты бюджетных обязательств между подведомственными распорядителями и (или)  получателями бюджетных средств,  если иное не установлено настоящим Кодексом;\n\nраспорядитель бюджетных средств (распорядитель средств соответствующего бюджета)  - орган государственной власти (государственный орган) ,  орган управления государственным внебюджетным фондом,  орган местного самоуправления,  орган местной администрации,  казенное учреждение,  имеющие право распределять бюджетные ассигнования и лимиты бюджетных обязательств между подведомственными распорядителями и (или)  получателями бюджетных средств; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nполучатель бюджетных средств (получатель средств соответствующего бюджета)  - орган государственной власти (государственный орган) ,  орган управления государственным внебюджетным фондом,  орган местного самоуправления,  орган местной администрации,  находящееся в ведении главного распорядителя (распорядителя)  бюджетных средств казенное учреждение,  имеющие право на принятие и (или)  исполнение бюджетных обязательств от имени публично-правового образования за счет средств соответствующего бюджета,  если иное не установлено настоящим Кодексом; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nказенное учреждение - государственное (муниципальное)  учреждение,  осуществляющее оказание государственных (муниципальных)  услуг,  выполнение работ и (или)  исполнение государственных (муниципальных)  функций в целях обеспечения реализации предусмотренных законодательством Российской Федерации полномочий органов государственной власти (государственных органов)  или органов местного самоуправления,  финансовое обеспечение деятельности которого осуществляется за счет средств соответствующего бюджета на основании бюджетной сметы; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nполучатель средств из бюджета - юридическое лицо (не являющееся участником бюджетного процесса,  бюджетным и автономным учреждением) ,  индивидуальный предприниматель,  физическое лицо - производитель товаров,  работ,  услуг,  получающие средства из бюджета на основании государственного (муниципального)  контракта на поставку товаров,  выполнение работ,  оказание услуг,  договора (соглашения)  о предоставлении субсидии,  договора о предоставлении бюджетных инвестиций,  а также юридическое лицо,  которому в случаях,  установленных федеральным законом,  открываются счета в Федеральном казначействе в соответствии с настоящим Кодексом; (Дополнение абзацем - Федеральный закон от 01.07.2021 № 244-ФЗ)\n\nбюджетная смета - документ,  устанавливающий в соответствии с классификацией расходов бюджетов лимиты бюджетных обязательств казенного учреждения; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nведомственная структура расходов бюджета - распределение бюджетных ассигнований,  предусмотренных законом (решением)  о бюджете,  по главным распорядителям бюджетных средств,  разделам,  подразделам,  целевым статьям,  группам (группам и подгруппам)  видов расходов бюджетов либо по главным распорядителям бюджетных средств,  разделам,  подразделам и (или)  целевым статьям (государственным (муниципальным)  программам и непрограммным направлениям деятельности) ,  группам (группам и подгруппам)  видов расходов классификации расходов бюджетов; (В редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\nадминистратор доходов бюджета - орган государственной власти (государственный орган) ,  орган местного самоуправления,  орган местной администрации,  орган управления государственным внебюджетным фондом,  Центральный банк Российской Федерации,  казенное учреждение,  осуществляющие в соответствии с законодательством Российской Федерации контроль за правильностью исчисления,  полнотой и своевременностью уплаты,  начисление,  учет,  взыскание и принятие решений о возврате (зачете)  излишне уплаченных (взысканных)  платежей,  пеней и штрафов по ним,  являющихся доходами бюджетов бюджетной системы Российской Федерации,  если иное не установлено настоящим Кодексом; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nглавный администратор доходов бюджета - определенный в соответствии с настоящим Кодексом орган государственной власти (государственный орган) ,  орган местного самоуправления,  орган местной администрации,  орган управления государственным внебюджетным фондом,  Центральный банк Российской Федерации,  иная организация,  имеющие в своем ведении администраторов доходов бюджета и (или)  являющиеся администраторами доходов бюджета; (В редакции Федерального закона от 01.07.2021 № 251-ФЗ)\n\nадминистратор источников финансирования дефицита бюджета (администратор источников финансирования дефицита соответствующего бюджета)  - орган государственной власти (государственный орган) ,  орган местного самоуправления,  орган местной администрации,  орган управления государственным внебюджетным фондом,  иная организация,  имеющие право в соответствии с настоящим Кодексом осуществлять операции с источниками финансирования дефицита бюджета;\n\nглавный администратор источников финансирования дефицита бюджета (главный администратор источников финансирования дефицита соответствующего бюджета)  - определенный в соответствии с настоящим Кодексом орган государственной власти (государственный орган) ,  орган местного самоуправления,  орган местной администрации,  орган управления государственным внебюджетным фондом,  иная организация,  имеющие в своем ведении администраторов источников финансирования дефицита бюджета и (или)  являющиеся администраторами источников финансирования дефицита бюджета; (В редакции Федерального закона от 01.07.2021 № 251-ФЗ)\n\nгосударственная или муниципальная гарантия (государственная гарантия Российской Федерации,  государственная гарантия субъекта Российской Федерации,  муниципальная гарантия)  - вид долгового обязательства,  в силу которого соответственно Российская Федерация,  субъект Российской Федерации,  муниципальное образование (гарант)  обязаны при наступлении предусмотренного в гарантии события (гарантийного случая)  уплатить лицу,  в пользу которого предоставлена гарантия (бенефициару) ,  по его письменному требованию определенную в обязательстве денежную сумму за счет средств соответствующего бюджета в соответствии с условиями даваемого гарантом обязательства отвечать за исполнение третьим лицом (принципалом)  его обязательств перед бенефициаром;\n\nобоснование бюджетных ассигнований - документ,  характеризующий бюджетные ассигнования в очередном финансовом году (очередном финансовом году и плановом периоде) ;\n\nлимит бюджетных обязательств - объем прав в денежном выражении на принятие казенным учреждением бюджетных обязательств и (или)  их исполнение в текущем финансовом году (текущем финансовом году и плановом периоде) ; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nтекущий финансовый год - год,  в котором осуществляется исполнение бюджета,  составление и рассмотрение проекта бюджета на очередной финансовый год (очередной финансовый год и плановый период) ;\n\nочередной финансовый год - год,  следующий за текущим финансовым годом;\n\nплановый период - два финансовых года,  следующие за очередным финансовым годом;\n\nотчетный финансовый год - год,  предшествующий текущему финансовому году;\n\nвременный кассовый разрыв - прогнозируемая в определенный период текущего финансового года недостаточность на едином казначейском счете или на едином счете бюджета денежных средств,  необходимых для осуществления перечислений из бюджета; (В редакции Федерального закона от 27.12.2019 № 479-ФЗ)\n\nдолговая устойчивость - состояние,  структура и сумма задолженности,  позволяющие заемщику в полном объеме выполнять обязательства по погашению и обслуживанию этой задолженности,  исключающие нанесение ущерба социально-экономическому развитию и необходимость ее списания и (или)  реструктуризации; (Дополнение абзацем - Федеральный закон от 02.08.2019 № 278-ФЗ)\n\nденежные обязательства перед публично-правовым образованием - обязанность должника уплатить публично-правовому образованию денежные средства по гражданско-правовой сделке (в том числе обеспечивающей исполнение обязательств)  и (или)  иному основанию,  установленному гражданским или бюджетным законодательством,  возникшая в связи с предоставлением публично-правовым образованием на возвратной и возмездной (возвратной)  основе денежных средств (в том числе в связи с привлечением целевых иностранных кредитов)  или в связи с предоставлением и (или)  исполнением государственной (муниципальной)  гарантии (включая обязанность по уплате процентов,  неустойки (пеней,  штрафов) ,  иных платежей,  установленных законом и (или)  договором,  вследствие неосновательного обогащения,  причинения убытков,  неисполнения или ненадлежащего исполнения обязательств,  уступки или перехода по иным основаниям прав требования,  предъявления регрессных требований) ; (Дополнение абзацем - Федеральный закон от 02.08.2019 № 278-ФЗ)\n\nвременно свободные средства - остаток денежных средств,  образовавшийся на едином казначейском счете или на едином счете бюджета вследствие разницы в сроках и объемах поступлений (зачислений)  на счет и переводов (перечислений)  со счета. (Дополнение абзацем - Федеральный закон от 27.12.2019 № 479-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n(Наименование в редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n(Глава в редакции Федерального закона от 20.08.2004 № 120-ФЗ)","article_title":"Статья 7. Бюджетные полномочия Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3378c4ce967c1de612876bab4434c77c5660c2dd5054e44ee6440c95b717c6b8"}]$law7d0036$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
